css:
.ap-art{position:relative;overflow:hidden}.ap-art svg{position:absolute;inset:0;width:100%;height:100%;display:block}
.fx-ld{width:min(1060px,100%);display:grid;gap:1.6em}
.fx-ld .top{display:flex;justify-content:space-between;align-items:end;gap:1em;flex-wrap:wrap}
.fx-ld h2{font-size:clamp(1.8em,4vw,2.6em)}.fx-ld .top p{opacity:.6;font-size:.95em;max-width:30em}
.fx-ld .grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:1.1em}
.fx-ld figure{margin:0;display:grid;gap:.6em}
.fx-ld figcaption{display:grid;gap:.1em}.fx-ld figcaption b{font:600 1em var(--font-heading)}.fx-ld figcaption span{font-size:.85em;opacity:.65}
.ld{position:relative;aspect-ratio:4/5;border-radius:var(--radius);overflow:hidden;touch-action:pan-y;background:var(--surface);border:1px solid var(--border);isolation:isolate}
.ld>svg,.ld>img{position:absolute;inset:0;width:100%;height:100%;display:block;object-fit:cover}
.ld>canvas{position:absolute;inset:0;width:100%;height:100%;display:block;opacity:0;transition:opacity calc(.4s/var(--speed))}
.ld.ld-ready>canvas{opacity:1}
@media(max-width:700px){.fx-ld .grid{grid-template-columns:repeat(2,minmax(0,1fr))}.fx-ld figure:last-child{grid-column:span 2}.fx-ld figure:last-child .ld{aspect-ratio:16/10}}

