(function(){
var tiles=[].slice.call(document.querySelectorAll('.fx-ld [data-ld]'));
if(!tiles.length||(window.matchMedia&&matchMedia('(prefers-reduced-motion:reduce)').matches))return;
var VS='attribute vec2 p;varying vec2 v;void main(){v=p*.5+.5;gl_Position=vec4(p,0.,1.);}';
var FS='precision mediump float;uniform sampler2D t;uniform vec2 m,sc;uniform float s,tm,asp;varying vec2 v;'+
'void main(){vec2 d=v-m;d.x*=asp;float r=length(d);float f=smoothstep(.55,0.,r);float w=sin(r*26.-tm*5.)*f;'+
'vec2 dir=r>.0001?d/r:vec2(0.);dir.x/=asp;vec2 u=v+dir*(w*.022*s)-(v-m)*f*.10*s;vec2 c=(u-.5)*sc+.5;float k=.006*s*f;'+
'gl_FragColor=vec4(texture2D(t,c+dir*k).r,texture2D(t,c).g,texture2D(t,c-dir*k).b,1.);}';
var VARS=['--primary','--secondary','--text','--accent','--surface','--border'];
function svgImage(svg,host,cb){
 var cs=getComputedStyle(host),css='svg{'+VARS.map(function(n){return n+':'+cs.getPropertyValue(n).trim()}).join(';')+'}';
 var c=svg.cloneNode(true);c.setAttribute('xmlns','http://www.w3.org/2000/svg');c.setAttribute('width','800');c.setAttribute('height','1000');
 var st=document.createElementNS('http://www.w3.org/2000/svg','style');st.textContent=css;c.insertBefore(st,c.firstChild);
 var im=new Image();im.onload=function(){cb(im)};im.onerror=function(){};
 im.src='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(new XMLSerializer().serializeToString(c))}
function init(el){
 var cv=document.createElement('canvas');cv.setAttribute('aria-hidden','true');
 var gl=cv.getContext('webgl',{premultipliedAlpha:false,antialias:false});if(!gl)return;
 function sh(type,src){var o=gl.createShader(type);gl.shaderSource(o,src);gl.compileShader(o);return gl.getShaderParameter(o,gl.COMPILE_STATUS)?o:null}
 var vs=sh(gl.VERTEX_SHADER,VS),fs=sh(gl.FRAGMENT_SHADER,FS);if(!vs||!fs)return;
 var pr=gl.createProgram();gl.attachShader(pr,vs);gl.attachShader(pr,fs);gl.linkProgram(pr);if(!gl.getProgramParameter(pr,gl.LINK_STATUS))return;
 gl.useProgram(pr);
 var b=gl.createBuffer();gl.bindBuffer(gl.ARRAY_BUFFER,b);gl.bufferData(gl.ARRAY_BUFFER,new Float32Array([-1,-1,1,-1,-1,1,1,1]),gl.STATIC_DRAW);
 var lp=gl.getAttribLocation(pr,'p');gl.enableVertexAttribArray(lp);gl.vertexAttribPointer(lp,2,gl.FLOAT,false,0,0);
 var U={};['t','m','sc','s','tm','asp'].forEach(function(n){U[n]=gl.getUniformLocation(pr,n)});
 var src=el.querySelector('img')||el.querySelector('svg');if(!src)return;
 function start(img){
  var tx=gl.createTexture();gl.bindTexture(gl.TEXTURE_2D,tx);gl.pixelStorei(gl.UNPACK_FLIP_Y_WEBGL,true);
  try{gl.texImage2D(gl.TEXTURE_2D,0,gl.RGBA,gl.RGBA,gl.UNSIGNED_BYTE,img)}catch(e){return}
  [[gl.TEXTURE_MIN_FILTER,gl.LINEAR],[gl.TEXTURE_MAG_FILTER,gl.LINEAR],[gl.TEXTURE_WRAP_S,gl.CLAMP_TO_EDGE],[gl.TEXTURE_WRAP_T,gl.CLAMP_TO_EDGE]].forEach(function(a){gl.texParameteri(gl.TEXTURE_2D,a[0],a[1])});
  el.appendChild(cv);
  var mx=.5,my=.5,s=0,tm=0,raf=0,last=0,W=0,H=0,iw=img.naturalWidth||img.width||800,ih=img.naturalHeight||img.height||1000,down=false;
  function size(){var r=el.getBoundingClientRect(),d=Math.min(window.devicePixelRatio||1,2);W=Math.max(2,Math.round(r.width*d));H=Math.max(2,Math.round(r.height*d));if(cv.width!==W||cv.height!==H){cv.width=W;cv.height=H}gl.viewport(0,0,W,H)}
  function draw(){
   var a=W/H,ia=iw/ih,sc=a>ia?[1,ia/a]:[a/ia,1];
   gl.uniform1i(U.t,0);gl.uniform2f(U.m,mx,my);gl.uniform2f(U.sc,sc[0],sc[1]);gl.uniform1f(U.s,s);gl.uniform1f(U.tm,tm);gl.uniform1f(U.asp,a);
   gl.drawArrays(gl.TRIANGLE_STRIP,0,4)}
  function tick(now){raf=0;var dt=Math.min(.05,(now-last)/1000||.016);last=now;tm+=dt;s*=Math.pow(.04,dt);if(s<.004)s=0;size();draw();if(s>0||down)raf=requestAnimationFrame(tick)}
  function kick(){if(!raf){last=performance.now();raf=requestAnimationFrame(tick)}}
  function pos(e){var r=el.getBoundingClientRect();return[(e.clientX-r.left)/r.width,1-(e.clientY-r.top)/r.height]}
  el.addEventListener('pointermove',function(e){var p=pos(e),dx=p[0]-mx,dy=p[1]-my;mx=p[0];my=p[1];
   s=Math.min(1,Math.max(s,Math.sqrt(dx*dx+dy*dy)*14+(down?.5:0)));kick()});
  el.addEventListener('pointerdown',function(e){var p=pos(e);mx=p[0];my=p[1];s=1;down=true;tm=0;kick()});
  addEventListener('pointerup',function(){down=false});
  el.addEventListener('pointerleave',function(){down=false});
  size();draw();el.classList.add('ld-ready');
  if(window.ResizeObserver)new ResizeObserver(function(){size();draw()}).observe(el);
  el.__ld={poke:function(x,y,v){mx=x;my=y;s=v;kick()}}}
 if(src.tagName==='IMG'){if(src.complete)start(src);else src.onload=function(){start(src)}}else svgImage(src,el,start)}
tiles.forEach(init);
})();
